def validate(records):
    if not 1 <= len(records) <= 50:
        return ["manifest has {} records; allowed range is 1..50".format(len(records))]
    problems = []
    seen_ids = set()
    for position, record in enumerate(records, 1):
        prefix = "record {}: ".format(position)
        if not isinstance(record, dict):
            problems.append(prefix + "must be an object")
            continue
        unknown = set(record) - {"load_id", "cartons", "note"}
        if unknown:
            problems.append(prefix + "unknown fields: " + ", ".join(sorted(unknown)))
        load_id = record.get("load_id")
        if not isinstance(load_id, str) or re.fullmatch(r"[a-z0-9-]{1,24}", load_id) is None:
            problems.append(prefix + "load_id must match [a-z0-9-]{1,24}")
        elif load_id in seen_ids:
            problems.append(prefix + "duplicate load_id " + load_id)
        else:
            seen_ids.add(load_id)
        cartons = record.get("cartons")
        if type(cartons) is not int or not 1 <= cartons <= 200:
            problems.append(prefix + "cartons must be an integer from 1 through 200")
        if "note" in record:
            note = record["note"]
            if not isinstance(note, str) or len(note) > 120:
                problems.append(prefix + "note must be a string of at most 120 characters")
    return problems
